-- =================================================================================================
-- UAT COPY (deploy/uat/uat-seed), made 2026-11-21 for the UAT RDS database core-uat-db / HR.
-- Identical to docs/test-data/sql except the "local development server only" guard (THROW 50002), which is
-- replaced by a guard that protects real data instead: see "UAT guard" below. Run in SSMS as the RDS master login.
-- =================================================================================================
-- =================================================================================================
-- Module sample data: DELETES the existing data of the modules and loads the demo's leave, attendance, payroll,
-- recruitment, KPI, grievance, activity and notification records.
-- Generated by ui/scripts/generate-db-seed.mjs on 2026-11-20 03:20 UTC from ui/src/app/mock-data. Do not edit
-- by hand: change the mock data and generate again. Dates relative to "today" were fixed on 2026-11-20, and today's
-- attendance shows only the check-ins made before the time it was generated (as the demo does at that time).
-- All data is fictional. Payroll figures are demonstrations, not statutory calculations.
--
-- LOCAL DEVELOPMENT DATABASE ONLY. A human runs this (Claude Code is not allowed to), AFTER
-- seed-organization-employees.sql of the same generation (it refuses to run when the sample employees and
-- organization units are not in the database):
--   sqlcmd -S "(localdb)\MSSQLLocalDB" -d HR -E -b -i docs\test-data\sql\seed-organization-employees.sql
--   sqlcmd -S "(localdb)\MSSQLLocalDB" -d HR -E -b -i docs\test-data\sql\seed-modules.sql
-- It can be run again on its own (it deletes the module data first), for example after creating the sample user
-- accounts (see "User ids" below).
--
-- What it does, in one transaction (any error rolls everything back):
--   1. Deletes the data of the modules, as seed-organization-employees.sql does in its step 1 (attendance, leave
--      applications, payroll runs and salary assignments, recruitment, KPI periods and scorecards, grievances with
--      their audit log, activity log, notifications, Excel import history), with the history of the temporal tables.
--   2. Adds the reference records the sample data needs when no record has their code (existing records are never
--      changed): leave types (AL, CL, ML, MAT, PAT, UL, CPL), 9 leave policies (by name), the 15 sample holidays
--      (by date), salary components and the structures STAFF, MGMT, EXEC (with their components), KPI categories and
--      templates, the default rating bands (only into an empty table) and grievance categories.
--   3. Inserts, with the ids of the demo:
--      Leave        29 leave applications (LV-...; the next number is 30)
--      Attendance   3342 attendance records (the last 60 days and today), 10 adjustment requests, 213 overtime entries
--      Payroll      107 salary assignments; 7 payroll runs (6 Paid months and the current month as Draft),
--                   327 payslips with 1686 lines
--      Recruitment  8 job openings, 22 candidates, 22 applications, 14 interviews
--      KPI          3 evaluation periods, 12 scorecards with 52 items and 35 review actions
--      Grievances   18 cases (2 drafts, 6 anonymous) with 73 status changes, 11 assignments, 7 investigation notes,
--                   3 messages, 4 file records, 2 corrective actions, 7 resolution proposals, 2 escalations
--      Activity     9 activity entries and 4 notifications (shown to every user)
--   4. Restarts the number sequences after the sample: leave LV-...-0030, job openings JOB-...-009,
--      grievance cases GRV-...-00017.
--
-- Triggers and history: the payroll and grievance "final" triggers refuse to insert a Paid run, its payslips or a
-- Closed case directly (those states are reached through the workflow). They are disabled while the sample is
-- loaded and enabled again before the commit. The temporal tables keep no history for the inserted rows.
--
-- User ids ("who did it"): the sample people act through their user accounts, looked up by employee when the
-- script runs (sec.AppUser.EmployeeId). A person without an account gets NULL, or minus their employee id (for
-- example -4 for May Thu Kyaw) in the columns that cannot be NULL and in grv.Escalation.EscalatedByUserId: user ids
-- start at 1, so it matches no account.
-- Create the sample accounts (Settings > Users) and run this script again to link the history to them.
--
-- Anonymous grievances: the submitter of an anonymous case is stored only as HMACSHA256(key, employee id). The
-- 6 anonymous sample cases use the labelled DEVELOPMENT key of api/src/Apex.Hrms.Api/appsettings.Development.json
-- (Grievance:PseudonymKey, "DEVELOPMENT-ONLY ... LocalDB only"). They appear under "My grievances" of their
-- submitter only while the API runs with that development key; with any other key nobody can find them again.
--
-- Files: the grievance file records have no files behind them (downloading one answers "The file of this
-- attachment is not available."). The leave documents and CVs are file names only, as in the demo.
-- =================================================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;

-- ---- Guards: the local HR database only, with the sample employees and organization ----------------
IF DB_NAME() <> N'HR'
    THROW 50001, N'Run this script in the local HR database only.', 1;
-- UAT guard: run only when the employees are exactly the 60 sample employees of seed-organization-employees.sql
-- (step 1 of this script deletes all module data).
IF (SELECT COUNT(*) FROM [hr].[Employee]) <> 60
    THROW 50002, N'UAT seed: the database must hold exactly the 60 sample employees (run seed-organization-employees.sql first, into an empty database).', 1;
IF EXISTS (
    SELECT v.[Id], v.[Code] FROM (VALUES
    (1, N'EMP001'),
    (2, N'EMP002'),
    (3, N'EMP003'),
    (4, N'EMP004'),
    (5, N'EMP005'),
    (6, N'EMP006'),
    (7, N'EMP007'),
    (8, N'EMP008'),
    (9, N'EMP009'),
    (10, N'EMP010'),
    (11, N'EMP011'),
    (12, N'EMP012'),
    (13, N'EMP013'),
    (14, N'EMP014'),
    (15, N'EMP015'),
    (16, N'EMP016'),
    (17, N'EMP017'),
    (18, N'EMP018'),
    (19, N'EMP019'),
    (20, N'EMP020'),
    (21, N'EMP021'),
    (22, N'EMP022'),
    (23, N'EMP023'),
    (24, N'EMP024'),
    (25, N'EMP025'),
    (26, N'EMP026'),
    (27, N'EMP027'),
    (28, N'EMP028'),
    (29, N'EMP029'),
    (30, N'EMP030'),
    (31, N'EMP031'),
    (32, N'EMP032'),
    (33, N'EMP033'),
    (34, N'EMP034'),
    (35, N'EMP035'),
    (36, N'EMP036'),
    (37, N'EMP037'),
    (38, N'EMP038'),
    (39, N'EMP039'),
    (40, N'EMP040'),
    (41, N'EMP041'),
    (42, N'EMP042'),
    (43, N'EMP043'),
    (44, N'EMP044'),
    (45, N'EMP045'),
    (46, N'EMP046'),
    (47, N'EMP047'),
    (48, N'EMP048'),
    (49, N'EMP049'),
    (50, N'EMP050'),
    (51, N'EMP051'),
    (52, N'EMP052'),
    (53, N'EMP053'),
    (54, N'EMP054'),
    (55, N'EMP055'),
    (56, N'EMP056'),
    (57, N'EMP057'),
    (58, N'EMP058'),
    (59, N'EMP059'),
    (60, N'EMP060')
    ) AS v ([Id], [Code])
    EXCEPT SELECT [Id], [EmployeeCode] FROM [hr].[Employee])
   OR EXISTS (
    SELECT v.[Kind], v.[Id], v.[Code] FROM (VALUES
    ('C', 1, N'AHT'),
    ('C', 2, N'AHL'),
    ('C', 3, N'AHV'),
    ('B', 1, N'YGN-HQ'),
    ('B', 2, N'MDY-BR'),
    ('B', 3, N'NPT-BR'),
    ('B', 4, N'MDY-DC'),
    ('B', 5, N'YGN-LH'),
    ('B', 6, N'SG-RO'),
    ('D', 1, N'EXEC'),
    ('D', 2, N'HR'),
    ('D', 3, N'FIN'),
    ('D', 4, N'ENG'),
    ('D', 5, N'PRD'),
    ('D', 6, N'SAL'),
    ('D', 7, N'IT'),
    ('D', 8, N'CS'),
    ('D', 9, N'OPS'),
    ('D', 10, N'LOG'),
    ('D', 11, N'MKT'),
    ('P', 1, N'POS-001'),
    ('P', 2, N'POS-002'),
    ('P', 3, N'POS-003'),
    ('P', 4, N'POS-004'),
    ('P', 5, N'POS-005'),
    ('P', 6, N'POS-006'),
    ('P', 7, N'POS-007'),
    ('P', 8, N'POS-008'),
    ('P', 9, N'POS-009'),
    ('P', 10, N'POS-010'),
    ('P', 11, N'POS-011'),
    ('P', 12, N'POS-012'),
    ('P', 13, N'POS-013'),
    ('P', 14, N'POS-014'),
    ('P', 15, N'POS-015'),
    ('P', 16, N'POS-016'),
    ('P', 17, N'POS-017'),
    ('P', 18, N'POS-018'),
    ('P', 19, N'POS-019'),
    ('P', 20, N'POS-020'),
    ('P', 21, N'POS-021'),
    ('P', 22, N'POS-022'),
    ('P', 23, N'POS-023'),
    ('P', 24, N'POS-024'),
    ('P', 25, N'POS-025'),
    ('P', 26, N'POS-026'),
    ('P', 27, N'POS-027'),
    ('P', 28, N'POS-028'),
    ('P', 29, N'POS-029'),
    ('P', 30, N'POS-030'),
    ('P', 31, N'POS-031'),
    ('P', 32, N'POS-032'),
    ('P', 33, N'POS-033'),
    ('G', 1, N'G1'),
    ('G', 2, N'G2'),
    ('G', 3, N'G3'),
    ('G', 4, N'G4'),
    ('G', 5, N'G5'),
    ('G', 6, N'G6'),
    ('G', 7, N'G7'),
    ('G', 8, N'G8'),
    ('G', 9, N'G9')
    ) AS v ([Kind], [Id], [Code])
    EXCEPT (SELECT 'C', [Id], [Code] FROM [org].[Company]
            UNION ALL SELECT 'B', [Id], [Code] FROM [org].[Branch]
            UNION ALL SELECT 'D', [Id], [Code] FROM [org].[Department]
            UNION ALL SELECT 'P', [Id], [Code] FROM [org].[Position]
            UNION ALL SELECT 'G', [Id], [Code] FROM [org].[JobGrade]))
    THROW 50003, N'The sample employees and organization units are not in this database (by id and code). Run seed-organization-employees.sql first.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

    -- ---- Triggers that forbid deleting paid runs and submitted or closed cases ----------------------
    DISABLE TRIGGER [pay].[TR_PayrollRun_PaidIsFinal] ON [pay].[PayrollRun];
    DISABLE TRIGGER [pay].[TR_PayrollRunWarning_PaidRunIsFinal] ON [pay].[PayrollRunWarning];
    DISABLE TRIGGER [pay].[TR_Payslip_PaidRunIsFinal] ON [pay].[Payslip];
    DISABLE TRIGGER [pay].[TR_PayslipLine_PaidRunIsFinal] ON [pay].[PayslipLine];
    DISABLE TRIGGER [grv].[TR_Attachment_Fixed] ON [grv].[Attachment];
    DISABLE TRIGGER [grv].[TR_Case_ClosedIsFinal] ON [grv].[Case];
    DISABLE TRIGGER [grv].[TR_Case_SubmittedIsFixed] ON [grv].[Case];

    -- ---- Temporal tables: versioning off while their rows and history are deleted -------------------
    ALTER TABLE [lve].[LeaveApplication]   SET (SYSTEM_VERSIONING = OFF);
    ALTER TABLE [pay].[PayrollRun]         SET (SYSTEM_VERSIONING = OFF);
    ALTER TABLE [pay].[SalaryAssignment]   SET (SYSTEM_VERSIONING = OFF);
    ALTER TABLE [kpi].[EvaluationPeriod]   SET (SYSTEM_VERSIONING = OFF);
    ALTER TABLE [kpi].[Scorecard]          SET (SYSTEM_VERSIONING = OFF);
    ALTER TABLE [kpi].[ScorecardItem]      SET (SYSTEM_VERSIONING = OFF);

    -- ---- 1. Delete the data of the modules -----------------------------------------------------------
    DELETE FROM [app].[Notification];
    DELETE FROM [app].[ActivityLog];
    DELETE FROM [app].[ImportIssue];
    DELETE FROM [app].[ImportBatch];

    DELETE FROM [grv].[Attachment];
    DELETE FROM [grv].[Assignment];
    DELETE FROM [grv].[CaseSubmitter];
    DELETE FROM [grv].[InvestigationNote];
    DELETE FROM [grv].[ResolutionProposal];
    DELETE FROM [grv].[StatusHistory];
    DELETE FROM [grv].[CorrectiveAction];
    DELETE FROM [grv].[Escalation];
    DELETE FROM [grv].[Communication];
    DELETE FROM [grv].[AuditLog];
    DELETE FROM [grv].[Case];

    DELETE FROM [kpi].[Attachment];
    DELETE FROM [kpi].[ReviewAction];
    DELETE FROM [kpi].[ScorecardItem];
    DELETE FROM [kpi].[Scorecard];
    DELETE FROM [kpi].[EvaluationPeriod];

    DELETE FROM [rec].[Interview];
    DELETE FROM [rec].[Application];
    DELETE FROM [rec].[JobOpening];
    DELETE FROM [rec].[Candidate];

    DELETE FROM [pay].[PayslipLine];
    DELETE FROM [pay].[Payslip];
    DELETE FROM [pay].[PayrollRunWarning];
    DELETE FROM [pay].[PayrollRun];
    DELETE FROM [pay].[SalaryAssignment];

    DELETE FROM [lve].[LeaveApplication];

    DELETE FROM [att].[AttendanceAdjustment];
    DELETE FROM [att].[AttendanceRecord];
    DELETE FROM [att].[OvertimeRecord];

    -- History of the temporal tables (dynamic SQL: it runs only once versioning is off).
    EXEC (N'DELETE FROM [lve].[LeaveApplicationHistory];
            DELETE FROM [pay].[PayrollRunHistory];
            DELETE FROM [pay].[SalaryAssignmentHistory];
            DELETE FROM [kpi].[EvaluationPeriodHistory];
            DELETE FROM [kpi].[ScorecardHistory];
            DELETE FROM [kpi].[ScorecardItemHistory];');

    ALTER TABLE [lve].[LeaveApplication]   SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [lve].[LeaveApplicationHistory], DATA_CONSISTENCY_CHECK = ON));
    ALTER TABLE [pay].[PayrollRun]         SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [pay].[PayrollRunHistory], DATA_CONSISTENCY_CHECK = ON));
    ALTER TABLE [pay].[SalaryAssignment]   SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [pay].[SalaryAssignmentHistory], DATA_CONSISTENCY_CHECK = ON));
    ALTER TABLE [kpi].[EvaluationPeriod]   SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [kpi].[EvaluationPeriodHistory], DATA_CONSISTENCY_CHECK = ON));
    ALTER TABLE [kpi].[Scorecard]          SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [kpi].[ScorecardHistory], DATA_CONSISTENCY_CHECK = ON));
    ALTER TABLE [kpi].[ScorecardItem]      SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [kpi].[ScorecardItemHistory], DATA_CONSISTENCY_CHECK = ON));

    -- Emptied tables number from 1 again (only the tables listed here, and only when they are empty).
    DECLARE @Reseed nvarchar(max) = N'';
    SELECT @Reseed += N'IF NOT EXISTS (SELECT 1 FROM ' + QUOTENAME(s.[name]) + N'.' + QUOTENAME(t.[name]) + N') '
                    + N'DBCC CHECKIDENT (N''' + QUOTENAME(s.[name]) + N'.' + QUOTENAME(t.[name]) + N''', RESEED, 0) WITH NO_INFOMSGS;'
    FROM sys.identity_columns AS ic
    JOIN sys.tables AS t ON t.[object_id] = ic.[object_id]
    JOIN sys.schemas AS s ON s.[schema_id] = t.[schema_id]
    JOIN (VALUES
    (N'att', N'AttendanceRecord'),
    (N'att', N'AttendanceAdjustment'),
    (N'att', N'OvertimeRecord'),
    (N'lve', N'LeaveApplication'),
    (N'pay', N'PayrollRun'),
    (N'pay', N'PayrollRunWarning'),
    (N'pay', N'Payslip'),
    (N'pay', N'PayslipLine'),
    (N'pay', N'SalaryAssignment'),
    (N'rec', N'JobOpening'),
    (N'rec', N'Candidate'),
    (N'rec', N'Application'),
    (N'rec', N'Interview'),
    (N'kpi', N'EvaluationPeriod'),
    (N'kpi', N'Scorecard'),
    (N'kpi', N'ScorecardItem'),
    (N'kpi', N'ReviewAction'),
    (N'kpi', N'Attachment'),
    (N'grv', N'Case'),
    (N'grv', N'Assignment'),
    (N'grv', N'Attachment'),
    (N'grv', N'AuditLog'),
    (N'grv', N'Communication'),
    (N'grv', N'CorrectiveAction'),
    (N'grv', N'Escalation'),
    (N'grv', N'InvestigationNote'),
    (N'grv', N'ResolutionProposal'),
    (N'grv', N'StatusHistory'),
    (N'app', N'ActivityLog'),
    (N'app', N'Notification'),
    (N'app', N'ImportIssue')
    ) AS l ([Schema], [Table]) ON l.[Schema] = s.[name] AND l.[Table] = t.[name]
    WHERE ic.[last_value] IS NOT NULL;
    EXEC sys.sp_executesql @Reseed;

    -- ---- 2. Reference data the sample needs (added when missing; never changed) ----------------------
    INSERT INTO [lve].[LeaveType]
        ([Code], [Name], [Description], [DefaultDaysPerYear], [IsPaid], [RequiresDocument], [MaxConsecutiveDays],
         [CarryForward], [MaxCarryForwardDays], [Color], [EligibleGender], [Status])
    SELECT v.[Code], v.[Name], v.[Description], v.[DefaultDaysPerYear], v.[IsPaid], v.[RequiresDocument],
           v.[MaxConsecutiveDays], v.[CarryForward], v.[MaxCarryForwardDays], v.[Color], v.[EligibleGender], v.[Status]
    FROM (VALUES
    (N'AL', N'Annual Leave', N'Paid vacation leave accrued annually.', 15, 1, 0, 10, 1, 5, '#3f6fd8', CAST(NULL AS varchar(30)), 'Active'),
    (N'CL', N'Casual Leave', N'Short paid leave for personal matters.', 6, 1, 0, 3, 0, 0, '#0f9d76', CAST(NULL AS varchar(30)), 'Active'),
    (N'ML', N'Medical Leave', N'Paid sick leave. Medical certificate required beyond 2 days.', 30, 1, 1, 30, 0, 0, '#d84a3f', CAST(NULL AS varchar(30)), 'Active'),
    (N'MAT', N'Maternity Leave', N'Leave for childbirth and post-natal care.', 98, 1, 1, 98, 0, 0, '#c2408f', 'Female', 'Active'),
    (N'PAT', N'Paternity Leave', N'Leave for fathers following the birth of a child.', 15, 1, 1, 15, 0, 0, '#8a4fd1', 'Male', 'Active'),
    (N'UL', N'Unpaid Leave', N'Leave without pay, subject to management approval.', 30, 0, 0, 30, 0, 0, '#6b7280', CAST(NULL AS varchar(30)), 'Active'),
    (N'CPL', N'Compassionate Leave', N'Paid leave on bereavement of an immediate family member.', 5, 1, 0, 5, 0, 0, '#c77700', CAST(NULL AS varchar(30)), 'Active')
    ) AS v ([Code], [Name], [Description], [DefaultDaysPerYear], [IsPaid], [RequiresDocument], [MaxConsecutiveDays],
            [CarryForward], [MaxCarryForwardDays], [Color], [EligibleGender], [Status])
    WHERE NOT EXISTS (SELECT 1 FROM [lve].[LeaveType] AS t WHERE t.[Code] = v.[Code]);

    -- Leave policies by name; skipped when an active policy already covers the same leave type, grade and type.
    INSERT INTO [lve].[LeavePolicy] ([Name], [LeaveTypeId], [JobGradeId], [EmploymentType], [DaysPerYear], [Accrual], [MinServiceMonths], [Status])
    SELECT v.[Name], t.[Id], g.[Id], v.[EmploymentType], v.[DaysPerYear], v.[Accrual], v.[MinServiceMonths], v.[Status]
    FROM (VALUES
    (N'Annual leave ' + NCHAR(8212) + N' standard (after 3 months)', N'AL', CAST(NULL AS nvarchar(20)), CAST(NULL AS varchar(30)), 15, 'Upfront', 3, 'Active'),
    (N'Annual leave ' + NCHAR(8212) + N' managers', N'AL', N'G6', CAST(NULL AS varchar(30)), 18, 'Upfront', 0, 'Active'),
    (N'Annual leave ' + NCHAR(8212) + N' senior managers', N'AL', N'G7', CAST(NULL AS varchar(30)), 20, 'Upfront', 0, 'Active'),
    (N'Annual leave ' + NCHAR(8212) + N' directors', N'AL', N'G8', CAST(NULL AS varchar(30)), 22, 'Upfront', 0, 'Active'),
    (N'Annual leave ' + NCHAR(8212) + N' executives', N'AL', N'G9', CAST(NULL AS varchar(30)), 25, 'Upfront', 0, 'Active'),
    (N'Annual leave ' + NCHAR(8212) + N' contract staff', N'AL', CAST(NULL AS nvarchar(20)), 'Contract', 10, 'Upfront', 0, 'Active'),
    (N'Annual leave ' + NCHAR(8212) + N' interns', N'AL', CAST(NULL AS nvarchar(20)), 'Intern', 6, 'Monthly', 0, 'Active'),
    (N'Casual leave ' + NCHAR(8212) + N' all staff (monthly accrual)', N'CL', CAST(NULL AS nvarchar(20)), CAST(NULL AS varchar(30)), 6, 'Monthly', 0, 'Active'),
    (N'Medical leave ' + NCHAR(8212) + N' interns', N'ML', CAST(NULL AS nvarchar(20)), 'Intern', 10, 'Upfront', 0, 'Active')
    ) AS v ([Name], [LeaveTypeCode], [GradeCode], [EmploymentType], [DaysPerYear], [Accrual], [MinServiceMonths], [Status])
    JOIN [lve].[LeaveType] AS t ON t.[Code] = v.[LeaveTypeCode]
    LEFT JOIN [org].[JobGrade] AS g ON g.[Code] = v.[GradeCode]
    WHERE (v.[GradeCode] IS NULL OR g.[Id] IS NOT NULL)
      AND NOT EXISTS (SELECT 1 FROM [lve].[LeavePolicy] AS p WHERE p.[Name] = v.[Name])
      AND NOT EXISTS (SELECT 1 FROM [lve].[LeavePolicy] AS p
                      WHERE p.[Status] = 'Active' AND v.[Status] = 'Active' AND p.[LeaveTypeId] = t.[Id]
                        AND (p.[JobGradeId] = g.[Id] OR (p.[JobGradeId] IS NULL AND g.[Id] IS NULL))
                        AND (p.[EmploymentType] = v.[EmploymentType] OR (p.[EmploymentType] IS NULL AND v.[EmploymentType] IS NULL)));

    -- Holidays (by date): leave days, payroll working days and the attendance "Holiday" days of the sample use them.
    INSERT INTO [att].[Holiday] ([Date], [Name], [Type])
    SELECT v.[Date], v.[Name], v.[Type]
    FROM (VALUES
    (CAST('2026-01-01' AS date), N'New Year''s Day', 'Public'),
    (CAST('2026-01-04' AS date), N'Independence Day', 'Public'),
    (CAST('2026-04-13' AS date), N'Water Festival', 'Public'),
    (CAST('2026-04-14' AS date), N'Water Festival', 'Public'),
    (CAST('2026-04-15' AS date), N'Water Festival', 'Public'),
    (CAST('2026-04-16' AS date), N'Water Festival', 'Public'),
    (CAST('2026-04-17' AS date), N'New Year Holiday', 'Public'),
    (CAST('2026-05-01' AS date), N'Labour Day', 'Public'),
    (CAST('2026-10-23' AS date), N'Festival of Lights', 'Public'),
    (CAST('2026-11-20' AS date), N'Company Foundation Day', 'Company'),
    (CAST('2026-11-23' AS date), N'Full Moon Festival', 'Public'),
    (CAST('2026-12-25' AS date), N'Christmas Day', 'Public'),
    (CAST('2026-12-31' AS date), N'Year-End Holiday', 'Company'),
    (CAST('2027-01-01' AS date), N'New Year''s Day', 'Public'),
    (CAST('2027-01-04' AS date), N'Independence Day', 'Public')
    ) AS v ([Date], [Name], [Type])
    WHERE NOT EXISTS (SELECT 1 FROM [att].[Holiday] AS h WHERE h.[Date] = v.[Date]);

    INSERT INTO [pay].[SalaryComponent] ([Code], [Name], [Type], [Calculation], [Value], [Description], [Status])
    SELECT v.[Code], v.[Name], v.[Type], v.[Calculation], v.[Value], v.[Description], v.[Status]
    FROM (VALUES
    (N'HOUSING', N'Housing allowance', 'Earning', 'PercentOfBasic', 10.00, N'Contribution towards housing costs.', 'Active'),
    (N'TRANSPORT', N'Transport allowance', 'Earning', 'Fixed', 50000.00, N'Fixed monthly commuting allowance.', 'Active'),
    (N'MEAL', N'Meal allowance', 'Earning', 'Fixed', 30000.00, N'Fixed monthly meal allowance.', 'Active'),
    (N'PERFORMANCE', N'Performance allowance', 'Earning', 'PercentOfBasic', 5.00, N'Recurring allowance for management roles.', 'Active'),
    (N'EXECUTIVE', N'Executive allowance', 'Earning', 'Fixed', 300000.00, N'Fixed monthly allowance for executive roles.', 'Active'),
    (N'TAX', N'Sample income tax', 'Deduction', 'PercentOfGross', 5.00, N'Demonstration rate only ' + NCHAR(8212) + N' not a real tax calculation.', 'Active'),
    (N'SOCIAL', N'Sample social contribution', 'Deduction', 'PercentOfGross', 2.00, N'Demonstration rate only ' + NCHAR(8212) + N' not a statutory contribution.', 'Active'),
    (N'PENSION', N'Sample pension (employee)', 'Deduction', 'PercentOfBasic', 3.00, N'Not used by any structure yet.', 'Inactive')
    ) AS v ([Code], [Name], [Type], [Calculation], [Value], [Description], [Status])
    WHERE NOT EXISTS (SELECT 1 FROM [pay].[SalaryComponent] AS c WHERE c.[Code] = v.[Code]);

    DECLARE @NewStructure TABLE ([Id] int NOT NULL, [Code] nvarchar(20) NOT NULL);
    INSERT INTO [pay].[SalaryStructure] ([Code], [Name], [Description], [Status])
    OUTPUT inserted.[Id], inserted.[Code] INTO @NewStructure ([Id], [Code])
    SELECT v.[Code], v.[Name], v.[Description], v.[Status]
    FROM (VALUES
    (N'STAFF', N'Staff structure', N'Grades G1' + NCHAR(8211) + N'G5.', 'Active'),
    (N'MGMT', N'Management structure', N'Grades G6' + NCHAR(8211) + N'G7.', 'Active'),
    (N'EXEC', N'Executive structure', N'Grades G8' + NCHAR(8211) + N'G9.', 'Active')
    ) AS v ([Code], [Name], [Description], [Status])
    WHERE NOT EXISTS (SELECT 1 FROM [pay].[SalaryStructure] AS s WHERE s.[Code] = v.[Code]);

    INSERT INTO [pay].[SalaryStructureComponent] ([SalaryStructureId], [SalaryComponentId], [SortOrder])
    SELECT n.[Id], c.[Id], v.[SortOrder]
    FROM (VALUES
    (N'STAFF', N'HOUSING', 1),
    (N'STAFF', N'TRANSPORT', 2),
    (N'STAFF', N'MEAL', 3),
    (N'STAFF', N'TAX', 4),
    (N'STAFF', N'SOCIAL', 5),
    (N'MGMT', N'HOUSING', 1),
    (N'MGMT', N'TRANSPORT', 2),
    (N'MGMT', N'PERFORMANCE', 3),
    (N'MGMT', N'TAX', 4),
    (N'MGMT', N'SOCIAL', 5),
    (N'EXEC', N'HOUSING', 1),
    (N'EXEC', N'TRANSPORT', 2),
    (N'EXEC', N'EXECUTIVE', 3),
    (N'EXEC', N'TAX', 4),
    (N'EXEC', N'SOCIAL', 5)
    ) AS v ([StructureCode], [ComponentCode], [SortOrder])
    JOIN @NewStructure AS n ON n.[Code] = v.[StructureCode]
    JOIN [pay].[SalaryComponent] AS c ON c.[Code] = v.[ComponentCode];

    INSERT INTO [kpi].[Category] ([Code], [Name], [Description], [Status])
    SELECT v.[Code], v.[Name], v.[Description], v.[Status]
    FROM (VALUES
    (N'PRODUCTIVITY', N'Productivity', N'Output and volume of work delivered.', 'Active'),
    (N'QUALITY', N'Quality', N'Accuracy and defect-free delivery.', 'Active'),
    (N'ATTENDANCE', N'Attendance', N'Presence at work as scheduled.', 'Active'),
    (N'PUNCTUALITY', N'Punctuality', N'Starting and delivering on time.', 'Active'),
    (N'COMMUNICATION', N'Communication', N'Clear and timely communication.', 'Active'),
    (N'TEAMWORK', N'Teamwork', N'Collaboration and support for colleagues.', 'Active'),
    (N'LEADERSHIP', N'Leadership', N'Guiding, coaching and decision making.', 'Active'),
    (N'CUSTOMER-SAT', N'Customer Satisfaction', N'How customers rate the service they receive.', 'Active'),
    (N'TECHNICAL', N'Technical Skills', N'Depth and currency of job-related skills.', 'Active'),
    (N'PROBLEM-SOLVING', N'Problem Solving', N'Finding and fixing root causes.', 'Active'),
    (N'PROJECT-DELIVERY', N'Project Delivery', N'Delivering projects on scope, time and budget.', 'Active')
    ) AS v ([Code], [Name], [Description], [Status])
    WHERE NOT EXISTS (SELECT 1 FROM [kpi].[Category] AS c WHERE c.[Code] = v.[Code] OR c.[Name] = v.[Name]);

    INSERT INTO [kpi].[Template]
        ([Code], [Name], [Description], [CategoryId], [DepartmentId], [MeasurementType], [Unit], [Direction], [ScoringMethod],
         [DefaultTarget], [RangeMin], [RangeMax], [MaxRating], [DefaultWeight], [MaxAchievementPct], [Frequency], [Status])
    SELECT v.[Code], v.[Name], v.[Description], c.[Id], d.[Id], v.[MeasurementType], v.[Unit], v.[Direction], v.[ScoringMethod],
           v.[DefaultTarget], v.[RangeMin], v.[RangeMax], v.[MaxRating], v.[DefaultWeight], v.[MaxAchievementPct], v.[Frequency], v.[Status]
    FROM (VALUES
    (N'OUTPUT-TASKS', N'Tasks completed', N'Planned tasks finished in the period. Beating the target is rewarded in full.', N'PRODUCTIVITY', CAST(NULL AS nvarchar(20)), 'Number', N'tasks', 'Higher Is Better', 'Direct Percentage', CAST(100 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(30 AS decimal(5, 2)), CAST(NULL AS decimal(8, 2)), 'Quarterly', 'Active'),
    (N'DEFECT-RATE', N'Defect rate', N'Share of delivered work that needed rework. Lower is better; zero scores the cap.', N'QUALITY', CAST(NULL AS nvarchar(20)), 'Percentage', N'%', 'Lower Is Better', 'Capped Percentage', CAST(5 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(20 AS decimal(5, 2)), CAST(120 AS decimal(8, 2)), 'Quarterly', 'Active'),
    (N'ATTENDANCE-RATE', N'Attendance rate', N'Scheduled days attended.', N'ATTENDANCE', CAST(NULL AS nvarchar(20)), 'Percentage', N'%', 'Higher Is Better', 'Capped Percentage', CAST(95 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(10 AS decimal(5, 2)), CAST(105 AS decimal(8, 2)), 'Quarterly', 'Active'),
    (N'BUDGET-ADHERENCE', N'Budget adherence', N'Spend close to the approved budget. Both overspending and underspending lose points.', N'PROJECT-DELIVERY', CAST(NULL AS nvarchar(20)), 'Currency', N'MMK', 'Exact Target', 'Direct Percentage', CAST(50000 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(30 AS decimal(5, 2)), CAST(NULL AS decimal(8, 2)), 'Quarterly', 'Active'),
    (N'CUSTOMER-RATING', N'Customer rating', N'Average customer rating on a 5 point scale.', N'CUSTOMER-SAT', CAST(NULL AS nvarchar(20)), 'Rating', N'points', 'Higher Is Better', 'Rating Based', CAST(5 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(5 AS decimal(18, 4)), CAST(25 AS decimal(5, 2)), CAST(NULL AS decimal(8, 2)), 'Quarterly', 'Active'),
    (N'TRAINING-DONE', N'Mandatory training completed', N'Yes or no: the required training was completed.', N'TEAMWORK', CAST(NULL AS nvarchar(20)), 'Boolean', CAST(NULL AS nvarchar(20)), 'Higher Is Better', 'Boolean', CAST(1 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(10 AS decimal(5, 2)), CAST(NULL AS decimal(8, 2)), 'Yearly', 'Active'),
    (N'RESPONSE-HOURS', N'Response time', N'Hours to first reply. Between 2 and 4 hours is on target.', N'COMMUNICATION', CAST(NULL AS nvarchar(20)), 'Hours', N'hours', 'Range Based', 'Range Based', CAST(3 AS decimal(18, 4)), CAST(2 AS decimal(18, 4)), CAST(4 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(15 AS decimal(5, 2)), CAST(NULL AS decimal(8, 2)), 'Monthly', 'Active'),
    (N'ENG-REVIEW-HOURS', N'Code review turnaround', N'Hours to review a pull request. Engineering only. Lower is better.', N'TECHNICAL', N'ENG', 'Hours', N'hours', 'Lower Is Better', 'Capped Percentage', CAST(24 AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(NULL AS decimal(18, 4)), CAST(30 AS decimal(5, 2)), CAST(110 AS decimal(8, 2)), 'Quarterly', 'Active')
    ) AS v ([Code], [Name], [Description], [CategoryCode], [DepartmentCode], [MeasurementType], [Unit], [Direction],
            [ScoringMethod], [DefaultTarget], [RangeMin], [RangeMax], [MaxRating], [DefaultWeight], [MaxAchievementPct],
            [Frequency], [Status])
    JOIN [kpi].[Category] AS c ON c.[Code] = v.[CategoryCode]
    LEFT JOIN [org].[Department] AS d ON d.[Code] = v.[DepartmentCode]
    WHERE (v.[DepartmentCode] IS NULL OR d.[Id] IS NOT NULL)
      AND NOT EXISTS (SELECT 1 FROM [kpi].[Template] AS t WHERE t.[Code] = v.[Code]);

    IF NOT EXISTS (SELECT 1 FROM [kpi].[RatingBand])
        INSERT INTO [kpi].[RatingBand] ([Label], [MinScore], [Description])
        VALUES
        (N'Outstanding', 90, N'Consistently exceeds every target.'),
        (N'Exceeds Expectations', 75, N'Exceeds most targets.'),
        (N'Meets Expectations', 60, N'Meets the agreed targets.'),
        (N'Needs Improvement', 40, N'Misses several targets; a development plan is expected.'),
        (N'Unsatisfactory', 0, N'Misses most targets.');

    INSERT INTO [grv].[Category] ([Code], [Name], [Description], [AllowsAnonymous], [DefaultTargetDays], [SortOrder], [Status])
    SELECT v.[Code], v.[Name], v.[Description], v.[AllowsAnonymous], v.[DefaultTargetDays], v.[SortOrder], v.[Status]
    FROM (VALUES
    (N'HARASSMENT', N'Workplace Harassment', N'Bullying, intimidation, sexual or other harassment at work.', 1, 14, 1, 'Active'),
    (N'DISCRIMINATION', N'Discrimination', N'Unequal treatment because of a protected characteristic.', 1, 14, 2, 'Active'),
    (N'COMPENSATION', N'Salary and Compensation Issues', N'Pay, allowances, deductions or benefits.', 0, 21, 3, 'Active'),
    (N'SAFETY', N'Workplace Safety', N'Unsafe conditions, equipment or practices.', 1, 7, 4, 'Active'),
    (N'RELATIONS', N'Employee Relations', N'Conflicts between colleagues or within a team.', 1, 30, 5, 'Active'),
    (N'MISCONDUCT', N'Management Misconduct', N'Abuse of authority or improper conduct by a manager.', 1, 21, 6, 'Active'),
    (N'UNFAIR-TREATMENT', N'Unfair Treatment', N'Unfair decisions on assignments, appraisals, promotion or discipline.', 1, 30, 7, 'Active'),
    (N'POLICY', N'Policy Violations', N'A company policy or procedure that is not being followed.', 1, 30, 8, 'Active'),
    (N'CONDITIONS', N'Working Conditions', N'Working hours, workload, facilities or the work environment.', 1, 30, 9, 'Active'),
    (N'OTHER', N'Other', N'Anything that does not fit another category.', 1, 30, 10, 'Active')
    ) AS v ([Code], [Name], [Description], [AllowsAnonymous], [DefaultTargetDays], [SortOrder], [Status])
    WHERE NOT EXISTS (SELECT 1 FROM [grv].[Category] AS c WHERE c.[Code] = v.[Code] OR c.[Name] = v.[Name]);

